ALTER TABLE public.bots ADD COLUMN platform text NOT NULL DEFAULT 'telegram', ADD COLUMN category text NOT NULL DEFAULT 'tools', ADD COLUMN price_1 bigint, ADD COLUMN price_3 bigint, ADD COLUMN price_6 bigint, ADD COLUMN price_12 bigint;
UPDATE public.bots SET category = CASE WHEN slug = 'self-bot' THEN 'account' WHEN slug IN ('group-manager','content-guard') THEN 'group' ELSE 'tools' END;
ALTER TABLE public.bots ADD CONSTRAINT bots_platform_valid CHECK (platform IN ('telegram','instagram','bale','eitaa','rubika')), ADD CONSTRAINT bots_category_valid CHECK (category IN ('group','account','ai','business','tools')), ADD CONSTRAINT bots_subscription_prices_valid CHECK ((price_1 IS NULL OR price_1 > 0) AND (price_3 IS NULL OR price_3 > 0) AND (price_6 IS NULL OR price_6 > 0) AND (price_12 IS NULL OR price_12 > 0));